      "keystrokes": "from bs4 import BeautifulSoup\n",
      "duration": 0.1
    },
    {
      "keystrokes": "\ndef remove_javascript(input_file):\n",
      "duration": 0.1
    },
    {
      "keystrokes": "    # Read content\n",
      "duration": 0.1
    },
    {
      "keystrokes": "    try:\n",
