    },
    {
      "keystrokes": "    soup = BeautifulSoup(content, 'html.parser')\n",
      "duration": 0.1
    },
    {
      "keystrokes": "\n",
      "duration": 0.1
    },
    {
      "keystrokes": "    # 1. Remove all script tags\n",
      "duration": 0.1
    },
    {
      "keystrokes": "    for script in soup(['script']):\n",
      "duration": 0.1
