      "keystrokes": "        attrs_to_remove = [attr for attr in tag.attrs if attr.lower().startswith('on')] \n",
      "duration": 0.1
    },
    {
      "keystrokes": "        for attr in attrs_to_remove:\n",
      "duration": 0.1
    },
    {
      "keystrokes": "            del tag[attr]\n",
      "duration": 0.1
    },
    {
      "keystroes": "\n",
      "duration": 0.1
    },
    {
      "keystrokes": "    # 3. Get the modified content\n",
